      "codeSnippet": "import { S3Client, PutObjectCommand } from \"@aws-sdk/client-s3\";\nimport crypto from \"node:crypto\";\n\nconst r2 = new S3Client({\n  region: \"auto\",\n  endpoint: `https://${process.env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com`,\n  credentials: {\n    accessKeyId: process.env.R2_ACCESS_KEY_ID,\n    secretAccessKey: process.env.R2_SECRET_ACCESS_KEY,\n  },\n});\n\nexport const uploadToR2 = async (fileBuffer, originalName, mimeType) => {\n  const fileKey = `uploads/${crypto.randomUUID()}-${originalName}`;\n\n  await r2.send(\n    new PutObjectCommand({\n      Bucket: process.env.R2_BUCKET_NAME,\n      Key: fileKey,\n      Body: fileBuffer,\n      ContentType: mimeType,\n    })\n  );\n\n  return `${process.env.R2_PUBLIC_DOMAIN}/${fileKey}`;\n};"
