      "tip": "Set exponential backoff retries on email jobs (`attempts: 5, backoff: { type: 'exponential', delay: 5000 }`) so temporary SMTP glitches don't drop emails.",
      "objective": "Dispatch email delivery tasks to a Redis-backed BullMQ queue.",
      "expectedOutcome": "Zero-latency email dispatch with automated retry resilience.",
      "codeSnippet": "import { Queue } from \"bullmq\";\n\n// 1. Initialize BullMQ Queue\nexport const emailQueue = new Queue(\"email-notifications\", {\n  connection: { host: process.env.REDIS_HOST, port: Number(process.env.REDIS_PORT) },\n});\n\n// 2. Dispatch email job inside Express Controller\nexport const triggerPasswordReset = async (req, res, next) => {\n  // ... generate resetToken ...\n\n  // Offload to BullMQ with 3 retries and exponential backoff\n  await emailQueue.add(\"send-reset-email\", {\n    email: user.email,\n    token: resetToken,\n  }, {\n    attempts: 3,\n    backoff: { type: \"exponential\", delay: 3000 },\n  });\n\n  res.json({ status: \"success\", message: \"Password reset link sent to your email!\" });\n};"
